import * as React from "react";
import { graphql, HeadFC, PageProps } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/layout";
import SEO from "../components/seo";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";

const userData = data;

const companyData: Company = {
  whatsapp: "",
  companyName: data.name,
  address: data.address,
  city: data.city,
  province: data.province,
  country: "Canada",
  phone: data.phone,
  email: data.email,
  instagram: data.instagram,
  facebook: data.facebook,
  menu: data.menu,
  linkedin: "",
  postalCode: data.postalCode,
  url: data.url,
};

const pageDescription = [data.address, data.city, data.province]
  .filter(Boolean)
  .join(", ");

const CruisesPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  const columns = [
    {
      image: images.wellness,
      title: t("cruisesPage.columns.one.title"),
      body: t("cruisesPage.columns.one.body"),
    },
    {
      image: images.gastronomy,
      title: t("cruisesPage.columns.two.title"),
      body: t("cruisesPage.columns.two.body"),
    },
    {
      image: images.culture,
      title: t("cruisesPage.columns.three.title"),
      body: t("cruisesPage.columns.three.body"),
    },
  ];

  const faqItems = [
    {
      question: t("cruisesPage.faq.items.one.question"),
      answer: t("cruisesPage.faq.items.one.answer"),
    },
    {
      question: t("cruisesPage.faq.items.two.question"),
      answer: t("cruisesPage.faq.items.two.answer"),
    },
    {
      question: t("cruisesPage.faq.items.three.question"),
      answer: t("cruisesPage.faq.items.three.answer"),
    },
    {
      question: t("cruisesPage.faq.items.four.question"),
      answer: t("cruisesPage.faq.items.four.answer"),
    },
  ];

  return (
    <Layout data={userData}>
      <section className={styles.page}>
        <article className={styles.hero}>
          <img
            className={styles.heroImage}
            src={images.cruisers.src}
            alt={images.cruisers.alt}
          />
          <div className={styles.heroOverlay}>
            <div className={styles.heroCopy}>
              <p className={styles.eyebrow}>{t("home.Cruises")}</p>
              <h1 className={styles.heroTitle}>{t("cruisesPage.hero.title")}</h1>
              <p className={styles.heroSubtitle}>{t("cruisesPage.hero.subtitle")}</p>
            </div>
          </div>
        </article>

        <article className={styles.columnsSection}>
          <div className={styles.columnsIntro}>
            <h2 className={styles.sectionTitle}>{t("cruisesPage.columnsHeading")}</h2>
            <p className={styles.sectionSubtitle}>{t("cruisesPage.columnsSubheading")}</p>
          </div>

          <div className={styles.columnsGrid}>
            {columns.map((column) => (
              <section key={column.title} className={styles.columnCard}>
                <img
                  className={styles.columnImage}
                  src={column.image.src}
                  alt={column.image.alt || column.title}
                />
                <div className={styles.columnBody}>
                  <h3 className={styles.columnTitle}>{column.title}</h3>
                  <p className={styles.columnText}>{column.body}</p>
                </div>
              </section>
            ))}
          </div>
        </article>

        <article className={styles.faqSection}>
          <div className={styles.faqShell}>
            <h2 className={styles.sectionTitle}>{t("cruisesPage.faq.heading")}</h2>
            <p className={styles.sectionSubtitle}>{t("cruisesPage.faq.subheading")}</p>

            <div className={styles.faqList}>
              {faqItems.map((item) => (
                <details key={item.question} className={styles.faqItem}>
                  <summary className={styles.faqQuestion}>{item.question}</summary>
                  <p className={styles.faqAnswer}>{item.answer}</p>
                </details>
              ))}
            </div>
          </div>
        </article>
      </section>
    </Layout>
  );
};

export default CruisesPage;

export const Head: HeadFC = ({ pageContext }) => {
  const i18n = (pageContext as
    | {
        i18n?: {
          language?: string;
          languages?: string[];
          defaultLanguage?: string;
          originalPath?: string;
        };
      }
    | undefined)?.i18n;

  return (
    <SEO
      data={companyData}
      title={userData.name}
      description={pageDescription || userData.name}
      schemaName={userData.name}
      pathname="/cruises"
      language={i18n?.language}
      languages={i18n?.languages}
      defaultLanguage={i18n?.defaultLanguage}
      originalPath={i18n?.originalPath}
    />
  );
};

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  page: "flex flex-col items-center",
  hero: "relative w-full",
  heroImage: "h-[42vh] min-h-[340px] w-full object-cover",
  heroOverlay: "absolute inset-0 bg-gradient-to-r from-secondary/85 via-secondary/60 to-secondary/20",
  heroCopy:
    "mx-auto flex h-full w-full max-w-[1400px] flex-col justify-center gap-3 px-4 py-12 text-contrast sm:px-8",
  eyebrow: "menu_desk uppercase tracking-[0.24em] text-contrast/80",
  heroTitle: "h1_desk max-w-4xl text-contrast",
  heroSubtitle: "body_desk max-w-2xl text-contrast/90",
  columnsSection: "w-full px-4 py-12 sm:px-8 sm:py-16",
  columnsIntro: "mx-auto flex max-w-[900px] flex-col gap-3 text-center",
  sectionTitle: "h2_desk text-secondary text-center font-bold",
  sectionSubtitle: "body_desk text-main text-center",
  columnsGrid: "mx-auto mt-10 grid max-w-[1400px] gap-6 lg:grid-cols-3",
  columnCard: "overflow-hidden bg-contrast shadow-lg",
  columnImage: "h-56 w-full object-cover",
  columnBody: "flex flex-col gap-3 p-6",
  columnTitle: "h3_desk text-secondary",
  columnText: "body_desk text-main/80",
  faqSection: "w-full bg-terciary/15 px-4 py-12 sm:px-8 sm:py-16",
  faqShell: "mx-auto flex max-w-[1000px] flex-col gap-4",
  faqList: "mt-6 flex flex-col gap-3",
  faqItem: "bg-contrast px-5 py-4 shadow-sm",
  faqQuestion: "h3_mobile cursor-pointer list-none text-secondary",
  faqAnswer: "body_desk mt-3 text-main/80",
};
